Input: {"question": "When was the Swedish Evangelical Lutheran Church built?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0476-939242695e3d:d00", "start": 0, "end": 148, "text": "Swedish Evangelical Lutheran Church (Ham Lake, Minnesota) The Swedish Evangelical Lutheran Church is a historic property in Anoka County, Minnesota."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0476-939242695e3d:d00", "start": 149, "end": 208, "text": "It is located at 2332 Swedish Drive in Ham Lake, Minnesota."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0476-939242695e3d:d00", "start": 209, "end": 307, "text": "The Late Victorian style church was built in 1872 to the design of architect Per August Gustafson."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0476-939242695e3d:d00", "start": 308, "end": 373, "text": "The church is listed on the National Register of Historic Places."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0476-939242695e3d:d00", "start": 374, "end": 548, "text": "The church is owned and maintained by the congregation of Our Savior's Lutheran Church of East Bethel, Minnesota and is also known as Our Saviors Lutheran Church of Ham Lake."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0476-939242695e3d:d00", "start": 549, "end": 626, "text": "Both churches are affiliated with the Evangelical Lutheran Church in America."}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 0, "end": 99, "text": "church : a one-story rear wing intended to provide space for a sacristy and Sunday School classes ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 100, "end": 199, "text": "Chronology 1872 Congregation builds the first rendition of the church and is served by Reverend J ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 200, "end": 202, "text": "A."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 203, "end": 245, "text": "Ausland , a travelling pastor from Anoka ."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 246, "end": 340, "text": "1891 An enclosed front entryway and bell tower are constructed on the church 's front façade ."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 341, "end": 420, "text": "1947 Third and final expansion project adds a Sunday school room and sacristy ."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 421, "end": 518, "text": "1964 Congregation moves to new facility but maintains the old structure for ceremonial purposes ."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0476-939242695e3d:d01", "start": 519, "end": 572, "text": "1979 The church is placed on the National Register of"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 0, "end": 226, "text": "Memory and high tribute to the pioneer families of the congregation, this memorial, erected in 1950 A.D., marks the site of the Swedish Evangelical Lutheran Church, now known as the Trinity Lutheran Church, Walnut Grove, Minn."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 227, "end": 272, "text": "The congregation was organized near here Nov."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 273, "end": 281, "text": "1, 1872."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 282, "end": 340, "text": "The church was erected in 1890 and was dismantled in 1925."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 341, "end": 360, "text": "Give God the glory!"}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 361, "end": 374, "text": "Erected 1950."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 375, "end": 382, "text": "Topics."}, "D3S8": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 383, "end": 456, "text": "This historical marker is listed in this topic list: Churches & Religion."}, "D3S9": {"document_number": 3, "doc_id": "ramdocs-0476-939242695e3d:d02", "start": 457, "end": 514, "text": "A significant historical date for this entry is November."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0476-939242695e3d:d03", "start": 0, "end": 168, "text": "Swedish Evangelical Lutheran Church (Millville, Minnesota) The Swedish Evangelical Lutheran Church is a historic church building in Millville, Minnesota, United States."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0476-939242695e3d:d03", "start": 169, "end": 270, "text": "It was built in 1874 and used successively by Swedish, Norwegian, and German immigrant congregations."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0476-939242695e3d:d03", "start": 271, "end": 443, "text": "The church and its adjacent cemetery were listed on the National Register of Historic Places in 1989 for having local significance in the theme of European ethnic heritage."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0476-939242695e3d:d03", "start": 444, "end": 567, "text": "It was nominated for being the only intact surviving ethnic church from the peak of European immigration to Wabasha County."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0476-939242695e3d:d03", "start": 568, "end": 667, "text": "The congregation was organized in 1869 by Swedish immigrant settlers in the area, but the community"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0476-939242695e3d:d04", "start": 0, "end": 269, "text": "Medicine Other lists Bridges National Historic Landmarks Voyageurs National Park Keeper of the Register History of the National Register of Historic Places Property types Historic district Contributing property Retrieved from `` https : //en.wikipedia.org/w/index.php ?"}, "D